        | PeerState.Failed -> "failed"
        | PeerState.Closed -> "closed"

    /// The wire text of a RemoteKind value.
    let wireRemoteKind (value: RemoteKind) : string =
        match value with
        | RemoteKind.Audio -> "audio"
        | RemoteKind.Video -> "video"

    let parseConnectionId (json: string) = Wire.parse decodeConnectionId json
    let serializeConnectionId (value: ConnectionId) = (encodeConnectionId value).ToJsonString()
    let parsePeerStaleReason (json: string) = Wire.parse decodePeerStaleReason json
    let serializePeerStaleReason (value: PeerStaleReason) = (encodePeerStaleReason value).ToJsonString()
    let parseSdpType (json: string) = Wire.parse decodeSdpType json
    let serializeSdpType (value: SdpType) = (encodeSdpType value).ToJsonString()
    let parseSessionDescription (json: string) = Wire.parse decodeSessionDescription json
    let serializeSessionDescription (value: SessionDescription) = (encodeSessionDescription value).ToJsonString()
    let parseIceCandidate (json: string) = Wire.parse decodeIceCandidate json
    let serializeIceCandidate (value: IceCandidate) = (encodeIceCandidate value).ToJsonString()
    let parseIceServer (json: string) = Wire.parse decodeIceServer json
    let serializeIceServer (value: IceServer) = (encodeIceServer value).ToJsonString()
    let parsePeerState (json: string) = Wire.parse decodePeerState json
    let serializePeerState (value: PeerState) = (encodePeerState value).ToJsonString()
    let parseRemoteKind (json: string) = Wire.parse decodeRemoteKind json
    let serializeRemoteKind (value: RemoteKind) = (encodeRemoteKind value).ToJsonString()
    let parseRemoteTarget (json: string) = Wire.parse decodeRemoteTarget json
    let serializeRemoteTarget (value: RemoteTarget) = (encodeRemoteTarget value).ToJsonString()
    let parsePeerRequest (json: string) = Wire.parse decodePeerRequest json
    let serializePeerRequest (value: PeerRequest) = (encodePeerRequest value).ToJsonString()
    let parsePeerResult (json: string) = Wire.parse decodePeerResult json
    let serializePeerResult (value: PeerResult) = (encodePeerResult value).ToJsonString()
    let parsePeerFact (json: string) = Wire.parse decodePeerFact json
    let serializePeerFact (value: PeerFact) = (encodePeerFact value).ToJsonString()

/// Decode-then-encode by type name. Used only by the shared conformance runner.
[<RequireQualifiedAccess>]
module Conformance =
    let roundTrips : Map<string, string -> JsonElement -> Result<JsonNode, DecodeError>> =
        Map.ofList [
            "ConnectionId", (fun path element -> Codec.decodeConnectionId path element |> Result.map Codec.encodeConnectionId)
            "PeerStaleReason", (fun path element -> Codec.decodePeerStaleReason path element |> Result.map Codec.encodePeerStaleReason)
            "SdpType", (fun path element -> Codec.decodeSdpType path element |> Result.map Codec.encodeSdpType)
            "SessionDescription", (fun path element -> Codec.decodeSessionDescription path element |> Result.map Codec.encodeSessionDescription)
            "IceCandidate", (fun path element -> Codec.decodeIceCandidate path element |> Result.map Codec.encodeIceCandidate)
            "IceServer", (fun path element -> Codec.decodeIceServer path element |> Result.map Codec.encodeIceServer)
            "PeerState", (fun path element -> Codec.decodePeerState path element |> Result.map Codec.encodePeerState)
            "RemoteKind", (fun path element -> Codec.decodeRemoteKind path element |> Result.map Codec.encodeRemoteKind)
            "RemoteTarget", (fun path element -> Codec.decodeRemoteTarget path element |> Result.map Codec.encodeRemoteTarget)
            "PeerRequest", (fun path element -> Codec.decodePeerRequest path element |> Result.map Codec.encodePeerRequest)
            "PeerResult", (fun path element -> Codec.decodePeerResult path element |> Result.map Codec.encodePeerResult)
            "PeerFact", (fun path element -> Codec.decodePeerFact path element |> Result.map Codec.encodePeerFact)
